/* Force Multiplier Block Academy 22.9.6 — mobile-first, fully offline */
(function(){'use strict';
const M=window.FMModel,B=window.FMBlockModel,root=document.getElementById('baApp'),STORE='fm-block-academy-2296';
if(!M||!B||!root){if(root)root.textContent='The offline training files were not loaded.';return;}
const escapeHTML=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const def=()=>({view:'home',level:'wave',cards:'scheduling',card:0,reveal:false,levelBoards:{},complete:{},reps:{},score:0,sound:true,message:null});
function load(){try{const stored=JSON.parse(localStorage.getItem(STORE)||'null');return stored&&stored.levelBoards?{...def(),...stored}:def()}catch{return def()}}
let s=load(),drag=null,suppressClickUntil=0;
function save(){try{localStorage.setItem(STORE,JSON.stringify(s))}catch{}}
function getBoard(id=s.level){if(!s.levelBoards[id]||typeof s.levelBoards[id]!=='object')s.levelBoards[id]={variation:0,metric:0,slots:{},marked:[],choice:null,resultChoice:null,active:'wave',assisted:false,stage:'find'};return s.levelBoards[id]}
function mission(){const b=getBoard();return B.makeMission(s.level,b.variation,b.metric,M)}
function tone(good){if(!s.sound)return;try{const context=new(window.AudioContext||window.webkitAudioContext)();const notes=good?[523,659,784]:[260,218],now=context.currentTime;notes.forEach((freq,i)=>{const o=context.createOscillator(),g=context.createGain();o.frequency.value=freq;o.type=good?'sine':'triangle';g.gain.setValueAtTime(.025,now+i*.07);g.gain.exponentialRampToValueAtTime(.001,now+.15+i*.07);o.connect(g);g.connect(context.destination);o.start(now+i*.07);o.stop(now+.16+i*.07)});setTimeout(()=>context.close(),700)}catch{}}
function notify(ok,message){s.message={ok,message};save();render();tone(ok)}
function openLevel(id){if(!B.LEVELS.some(l=>l.id===id))return;s.view='play';s.level=id;s.message=null;save();render();window.scrollTo(0,0)}
function navigate(view){s.view=view;s.message=null;save();render();window.scrollTo(0,0)}
function changeVariation(){const b=getBoard(),v=b.variation+1,metric=b.metric;s.levelBoards[s.level]={variation:v,metric,slots:{},marked:[],choice:null,resultChoice:null,active:'wave',assisted:false,stage:'find'};s.message=null;save();render()}
function reset(){const b=getBoard(),variation=b.variation,metric=b.metric;s.levelBoards[s.level]={variation,metric,slots:{},marked:[],choice:null,resultChoice:null,active:'wave',assisted:false,stage:'find'};s.message=null;save();render()}
function deck(which){if(which==='scheduling')return Object.entries(M.SCHED_VOCAB).map(([term,answer])=>({term,answer}));if(which==='doc')return [...Object.entries(M.DOC_TERMS).map(([term,answer])=>({term,answer})),{term:'Shared final cure',answer:'Only if the approved process permits, combined RED and GREEN work may share one passive final cure. Keep active work off nonwork days in this exercise.'}];if(which==='analysis')return [{term:'NMC time',answer:'Time that an aircraft is not mission capable during the measured period. Use its properly defined category and denominator when computing rates.'},...M.METRICS.map(x=>({term:x.name,answer:x.meaning+' Formula: '+x.num+' ÷ '+x.den+(x.mult===100?' × 100':'')+'.'}))];if(which==='integrity')return [...Object.entries(M.INTEGRITY_FIELDS).map(([term,answer])=>({term,answer})),...B.TERMS.integrity.map(([term,answer])=>({term,answer}))];return B.TERMS.dbm.map(([term,answer])=>({term,answer}))}
function miniStatus(){return `<div class="ba-stats"><span class="ba-rank">NON-NONNER <i>· status pending</i></span><span><b>${Object.keys(s.complete).length}</b>/7 cleared</span><span>★ ${s.score}</span></div>`}
function header(){return `<header class="ba-top"><a class="ba-round" href="./index.html" aria-label="Back to original Force Multiplier training">←</a><div class="ba-logo"><b>FORCE MULTIPLIER</b><small>REVENGE OF THE NONNER</small></div><button class="ba-round ba-sound" type="button" data-cmd="sound" aria-label="Toggle sounds" aria-pressed="${s.sound}">${s.sound?'♫':'♪̸'}</button></header>${miniStatus()}`}
function home(){const next=B.LEVELS.find(l=>!s.complete[l.id])||B.LEVELS[0];return `<div class="ba-home"><section class="ba-hero"><p class="ba-kicker">MAINTENANCE MANAGEMENT · BLOCK CAMPAIGN</p><h1>REVENGE OF<br><em>THE NONNER</em></h1><p>Move the blocks. Solve the problem. Save flying days. Maybe earn the privilege of working in the office.</p><div class="ba-hero-actions"><button class="ba-main-btn" data-start="${next.id}">▶ PLAY ${Object.keys(s.complete).length?'NEXT MISSION':'THE CAMPAIGN'}</button><span>NO TIMER · offline · tap or drag</span></div></section><section class="ba-section"><div class="ba-row"><div><p class="ba-kicker">THE SEVEN-MISSION CAMPAIGN</p><h2>Pick a puzzle</h2></div><b class="ba-mini-count">${Object.keys(s.complete).length}/7</b></div><div class="ba-missions">${B.LEVELS.map((x,i)=>`<button class="ba-mission" data-start="${x.id}"><span class="ba-mission-icon ${x.theme}">${['✈','▦','◩','▣','÷','≠','🔑'][i]}</span><span class="ba-mission-body"><small>${i+1} · ${E(x.label)}</small><strong>${E(x.title)}</strong><span>${E(x.short)}</span></span><b>${s.complete[x.id]?'✓':'›'}</b></button>`).join('')}</div></section><section class="ba-officer-teaser" style="background:linear-gradient(125deg,#144267,#0b2942);border-color:#4c93ba"><small>ANALYSIS · ADVANCED PRACTICE</small><strong>IMPROVEMENT LABORATORY</strong><span>Choose tests for trends, correlations, differences, proportions, and variation. Learn H₀, assumptions, p-values, and what results do not prove. No timer.</span><a href="./improvement-lab.html">OPEN THE STATISTICAL TEST LAB →</a></section><section class="ba-section ba-study-home"><p class="ba-kicker">LEARN THE LANGUAGE</p><h2>Flashcards by discipline</h2><div class="ba-deck-grid">${[['scheduling','Scheduling'],['doc','Documentation'],['analysis','Analysis'],['integrity','Data Integrity'],['dbm','Database & Systems']].map(([k,t])=>`<button data-deck="${k}" class="ba-deck">${E(t)} <span>↗</span></button>`).join('')}</div></section><section class="ba-officer-teaser"><small>INCOMING OFFICER REQUEST</small><strong>“ADD MORE JETS TO THE SCHEDULE!”</strong><span>Later, find out what happens to Phase Flow and the Maintenance Death Spiral when you say yes.</span><a href="./index.html#capstone">Take the 90-day challenge →</a></section><div class="ba-classic"><b>Ready for the full job?</b><p>The original detailed trainers and 90-day capstone are still here. All aircraft and people in these games are fictional.</p><a href="./index.html#capstone">OPEN 90-DAY SCHEDULING CAPSTONE →</a></div></div>`}
function cards(){const deckItems=deck(s.cards),idx=((s.card%deckItems.length)+deckItems.length)%deckItems.length,item=deckItems[idx];const shortcuts={scheduling:'wave',doc:'doc',analysis:'analysis',integrity:'integrity',dbm:'dbm'};return `<div class="ba-playing"><div class="ba-breadcrumb"><button data-cmd="home">‹ CAMPAIGN</button><span>VOCABULARY LAB</span></div><p class="ba-kicker">${E({scheduling:'SCHEDULING',doc:'DOCUMENTATION',analysis:'ANALYSIS',integrity:'DATA INTEGRITY',dbm:'DATABASE & SYSTEMS'}[s.cards])}</p><h1>Flip the card</h1><div class="ba-steps">Card ${idx+1} of ${deckItems.length} · no timer</div><button class="ba-flashcard ${s.reveal?'flipped':''}" data-cmd="flip" aria-label="${s.reveal?'View term':'Reveal definition'}"><span>${s.reveal?'THE ANSWER':'THE TERM'}</span><strong>${E(s.reveal?item.answer:item.term)}</strong><small>Tap to ${s.reveal?'see the question':'reveal the answer'} ↻</small></button><div class="ba-action-row"><button class="ba-alt" data-cmd="card-back">← Previous</button><button class="ba-main-btn" data-cmd="card-next">Next card →</button></div><button class="ba-outlined" data-start="${shortcuts[s.cards]}">Practice the blocks →</button><div class="ba-deck-grid ba-deck-bottom">${[['scheduling','Scheduling'],['doc','Documentation'],['analysis','Analysis'],['integrity','Data Integrity'],['dbm','Database']].map(([k,t])=>`<button data-deck="${k}" class="ba-deck ${s.cards===k?'selected':''}">${E(t)}</button>`).join('')}</div></div>`}
function stageCounts(id,b,m){return m.groups.map(([key,count,title])=>({key,count,title,filled:Array.from({length:count},(_,i)=>b.slots[key+':'+i]).filter(Boolean).length}))}
function tileInfo(m,id){if(m.aircraft){const x=m.aircraft.find(x=>x.id===id);if(!x)return {label:id,sub:'Unknown',status:'FMC',age:0};return {label:id,sub:x.status==='FMC'?(x.idle+'d idle'):(x.status==='HQ'?'30 days':x.status==='PHASE'?'0h to Phase':x.status==='MOD'?'PFR · planned':B.STATUSES[x.status]?.label||x.status),status:x.status,age:x.idle,hours:x.hours};}
 if(m.pieces){const x=m.pieces.find(x=>x[0]===id);return {label:x?x[1]:id,sub:x?x[2]:'',status:['r1','r2'].includes(id)?'RED':['g1','g2'].includes(id)?'GREEN':'CURE'};}
 return {label:id,sub:'',status:'WORD'};
}
function tileStyle(info){if(info.status==='FMC'){const a=info.age||0;return `style="--age:${Math.min(0.65,a/45).toFixed(2)}"`;}return''}
function tileClass(info){return ('ba-kind-'+String(info.status||'FMC').toLowerCase().replace(/[^a-z0-9]/g,''))}
function piece(m,id,fromBank=true){const info=tileInfo(m,id);return `<span class="ba-brick ${tileClass(info)}" ${tileStyle(info)} data-piece="${E(id)}" title="${E(info.sub)}"><b>${E(info.label)}</b><small>${E(info.sub)}</small></span>`}
function slot(m,b,key,i,label){const id=b.slots[key+':'+i],info=id?tileInfo(m,id):null;return `<button type="button" class="ba-slot ${id?'filled '+tileClass(info):''}" data-slot="${key}:${i}" aria-label="${E(label)} slot ${i+1}${id?' '+id:''}">${id?piece(m,id,false):`<span class="ba-slot-blank"><b>${i+1}</b><small>+</small></span>`}</button>`}
function lane(m,b,group){const [key,count,name]=group,filled=Array.from({length:count},(_,i)=>!!b.slots[key+':'+i]).filter(Boolean).length;const selected=(b.active||'wave')===key;return `<section class="ba-lane ${selected?'current':''}"><div class="ba-lane-header"><button type="button" data-lane="${key}" class="ba-lane-select" aria-pressed="${selected}">${E(name)} <small>${key==='turn'?'↻':'✈'}</small></button><b>${filled}/${count}</b></div><div class="ba-slots ${key==='turn'?'four':''} ${key==='hold'?'two':''}">${Array.from({length:count},(_,i)=>slot(m,b,key,i,name)).join('')}</div></section>`}
function bank(m,b){const items=m.aircraft||[];return `<section class="ba-bank"><div class="ba-bank-title"><h2>AIRCRAFT BLOCKS</h2><span>Touch or drag</span></div><div class="ba-bricks">${items.map(x=>`<button class="ba-bank-tile ${b.selected===x.id?'chosen':''}" type="button" data-bank="${E(x.id)}">${piece(m,x.id)}</button>`).join('')}</div></section>`}
function waveGame(m,b){const groups=stageCounts(m.id,b,m);return `<section class="ba-hangar"><div class="ba-hangar-sign"><span>✈ ${m.id==='wave'?'MONDAY':m.id==='status'?'TUESDAY':'WEDNESDAY'} DEPARTURE DOOR</span><small>ACFT SEQUENCING</small></div><div class="ba-hangar-light"></div>${m.groups.map(g=>lane(m,b,g)).join('')}<div class="ba-lane-help">${m.id==='phase'?'Fill each lane with the correct aircraft.':'Fill the first wave. Then tap “Turn aircraft” to assign four of those flyers again.'}</div></section>${bank(m,b)}<div class="ba-legend">${(m.id==='wave'?['FMC']:m.id==='phase'?['FMC','PHASE','NMCS']:['FMC','HQ','NMCM','NMCS','NMCB','PHASE','DEPOT','MOD']).map(st=>`<span><i class="${'ba-kind-'+st.toLowerCase()}"></i>${E(st==='MOD'?'PFR / MOD':st)}</span>`).join('')}</div>`}
function docTile(m,b,day,readonly=false){const cells=readonly?M.docDowntimeCase(m.variation).baseline:null;
 const stage=readonly?(cells[day]||null):(b.slots['day:'+(day-1)]||null);const weekend=M.docDowntimeWeekend(day);const name=stage===null?'':stage==='c'?'C':stage.toUpperCase();const body=`<b>${E(name||'·')}</b><small>${day}</small>`;
 return readonly?`<span class="ba-day ${weekend?'weekend':''} ${stage?'has-'+stage:''}" aria-label="Original day ${day}: ${name||'blank'}">${body}</span>`:`<button type="button" class="ba-day ${weekend?'weekend':''} ${stage?'has-'+stage:''}" data-slot="day:${day-1}" aria-label="Your day ${day} ${name||'empty'}">${body}</button>`;}
function docWeek(m,b,week,readonly){return `<div class="ba-doc-week"><div class="ba-weeklabel">WEEK ${week+1}</div><div class="ba-day-labels">${['M','T','W','T','F','S','S'].map((x,i)=>`<span class="${i>=5?'weekend':''}">${x}</span>`).join('')}</div><div class="ba-days">${Array.from({length:7},(_,i)=>docTile(m,b,week*7+i+1,readonly)).join('')}</div></div>`}
function docGame(m,b){const original=M.docDowntimeStats(M.docDowntimeCase(m.variation).baseline),current={};for(let d=1;d<=14;d++)if(b.slots['day:'+(d-1)])current[d]=b.slots['day:'+(d-1)];const now=M.docDowntimeStats(current);return `<section class="ba-board-box"><div class="ba-board-tag">THE INEFFICIENT PLAN <span>${original.cures} CURES · ${original.weekdays} WEEKDAYS DOWN</span></div><div class="ba-doc-board original">${[0,1].map(w=>docWeek(m,b,w,true)).join('')}</div></section><section class="ba-board-box"><div class="ba-board-tag good">YOUR REPAIRED PLAN <span>${now.cures} CURE · ${now.weekdays} DOWNTIME DAYS</span></div><div class="ba-doc-board">${[0,1].map(w=>docWeek(m,b,w,false)).join('')}</div></section><section class="ba-bank"><div class="ba-bank-title"><h2>MOVE THE WORK BLOCKS</h2><span>Tap, then tap a day</span></div><div class="ba-doc-bank">${m.pieces.map(x=>`<button class="ba-bank-tile ${b.selected===x[0]?'chosen':''}" data-bank="${x[0]}" type="button">${piece(m,x[0])}</button>`).join('')}</div><p class="ba-help">No active work Saturday or Sunday. The final passive 24-hour cure may run over the weekend, under this scenario’s approved combined-cure assumption.</p></section>`}
function analysisGame(m,b){const dims=m.groups,choices=m.formulaTokens;return `<section class="ba-metric-chooser"><label for="baMetric">PRACTICE ONE OF ${M.METRICS.length} METRICS</label><select id="baMetric" data-metric-change>${M.METRICS.map((x,i)=>`<option value="${i}" ${i===b.metric?'selected':''}>${E(x.name)}</option>`).join('')}</select></section><section class="ba-board-box ba-formula-game"><p class="ba-kicker">WHAT IS ${E(m.metric.name.toUpperCase())}?</p><p>${E(m.metric.meaning)}</p><div class="ba-rawnums"><div><b>${m.numerator}</b><small>${E(m.metric.num)}</small></div><span>÷</span><div><b>${m.denominator}</b><small>${E(m.metric.den)}</small></div>${m.metric.mult===100?'<span>× 100</span>':''}</div><div class="ba-formula"><div class="ba-formula-top">${slot(m,b,'num',0,'Numerator')}</div><div class="ba-fraction-bar"></div><div class="ba-formula-bottom">${slot(m,b,'den',0,'Denominator')}</div></div><div class="ba-word-bank">${choices.map(x=>`<button class="ba-word ${b.selected===x?'chosen':''}" data-bank="${E(x)}">${E(x)}</button>`).join('')}</div><p class="ba-help">Select a definition block, then tap Numerator or Denominator. You can also drag it into the formula.</p><div class="ba-result-question"><strong>CALCULATED RESULT</strong><div class="ba-results">${m.choices.map(v=>`<button data-number="${v}" class="ba-number ${b.resultChoice===v?'chosen':''}">${v}${m.metric.mult===100?'%':''}</button>`).join('')}</div></div></section>`}
function compareGame(m,b){const integrity=m.id==='integrity',items=m.records||[];const labels=integrity?['APPROVED SOURCE','SYSTEM RECORD']:['AUTHORIZED','ACTUAL ACCESS'];return `<section class="ba-compare"><div class="ba-compare-head"><span>${labels[0]}</span><span>${labels[1]}</span></div><div class="ba-compare-rows">${items.map((r,i)=>{const selected=b.marked.includes(r.id);const a=integrity?r.source:r.authorized,c=integrity?r.actual:r.actual;return `<button type="button" data-flag="${E(r.id)}" class="ba-compare-row ${selected?'flagged':''}" aria-pressed="${selected}"><span><b>${E(r.id)}</b><small>${E(integrity?r.field:r.user)}</small><strong>${E(a)}</strong></span><span><b>${selected?'✓ SELECTED':'TAP IF DIFFERENT'}</b><small>${E(integrity?r.field:r.user)}</small><strong>${E(c)}</strong></span></button>`}).join('')}</div><p class="ba-help">Tap the entire row to flag a discrepancy. Do not assume that a visually similar record is correct without checking its contents.</p></section>${b.stage==='decision'?`<section class="ba-decision"><div class="ba-kicker">INVESTIGATE BEFORE YOU ACT</div><h2>${integrity?'How should the source record be corrected?':'What should happen to unauthorized access?'}</h2>${m.choices.map(c=>`<button class="ba-decision-option ${b.choice===c.id?'chosen':''}" data-choice="${c.id}">${E(c.label)}</button>`).join('')}</section>`:`<div class="ba-selected-summary">${b.marked.length} of ${m.discrepancies.length} mismatches selected</div>`}`}
function noteMessage(){if(!s.message)return'';return `<div class="ba-feedback ${s.message.ok?'good':'bad'}" role="status"><strong>${s.message.ok?'✓':'!'} ${s.message.ok?'GOOD DECISION':'CHECK THE PLAN'}</strong><p>${E(s.message.message)}</p></div>`}
function footer(m,b){const complete=!!(s.message&&s.message.ok);const lvlIndex=B.LEVELS.findIndex(l=>l.id===m.id),next=B.LEVELS[(lvlIndex+1)%B.LEVELS.length];return `<div class="ba-controls"><div class="ba-main-actions"><button type="button" data-cmd="check" class="ba-main-btn">${m.id==='wave'||m.id==='status'?'✈ LAUNCH WAVE':m.id==='doc'?'✓ CHECK SAVINGS':m.id==='analysis'?'÷ CHECK THE RATE':'✓ CHECK PLAN'}</button><button type="button" data-cmd="reset" class="ba-alt" aria-label="Reset the current puzzle">↺</button></div>${noteMessage()}${complete?`<div class="ba-win-banner"><span>★</span><div><b>MISSION CLEARED</b><p>Nonner status: still pending higher approval.${m.id==='doc'?' The H in Documentation stands for Happiness.':''}</p></div></div><div class="ba-action-row"><button class="ba-alt" data-cmd="variation">↻ Play again</button><button class="ba-main-btn" data-start="${next.id}">${lvlIndex===B.LEVELS.length-1?'Campaign again':'Next mission →'}</button></div>`:''}<div class="ba-secondary-actions"><button data-cmd="hint">Hint</button><button data-cmd="model">Show model</button><button data-cmd="variation">New variation</button></div><div class="ba-training-link"><a href="./index.html#${m.id==='status'||m.id==='phase'||m.id==='wave'?'scheduling':m.id}">Open full ${E(B.LEVELS.find(x=>x.id===m.id).label)} trainer ↗</a></div></div>`}
function play(){const m=mission(),b=getBoard();const name=B.LEVELS.find(x=>x.id===s.level);return `<div class="ba-playing"><div class="ba-breadcrumb"><button data-cmd="home">‹ CAMPAIGN</button><span>LEVEL ${B.LEVELS.findIndex(x=>x.id===m.id)+1} / 7</span><button data-deck="${m.id==='wave'||m.id==='status'||m.id==='phase'?'scheduling':m.id}" class="ba-study-link">Study terms ↗</button></div><div class="ba-playing-head"><span class="ba-pill">${E(name.label.toUpperCase())}</span><h1>${E(m.title)}</h1><p>${E(m.requirement)}</p></div>${['wave','status','phase'].includes(m.id)?waveGame(m,b):m.id==='doc'?docGame(m,b):m.id==='analysis'?analysisGame(m,b):compareGame(m,b)}${footer(m,b)}</div>`}
function render(){root.innerHTML=header()+(s.view==='cards'?cards():s.view==='play'?play():home());}
function groupFor(m,k){return m.groups?.find(([key])=>key===k)}
function place(pieceID,dest,sourceKey=null){const m=mission(),b=getBoard(),[lane,indexS]=dest.split(':'),index=Number(indexS),group=groupFor(m,lane);
 if(!group||!Number.isInteger(index)||index<0||index>=group[1])return;
 const available=m.aircraft?m.aircraft.some(x=>x.id===pieceID):m.pieces?m.pieces.some(x=>x[0]===pieceID):m.formulaTokens?m.formulaTokens.includes(pieceID):false;
 if(!available)return;
 const previous=b.slots[dest]||null;
 const uniqueGroups=m.id==='wave'||m.id==='status'?([lane]):m.id==='analysis'?([lane]):m.groups.map(g=>g[0]);
 for(const key of Object.keys(b.slots))if(uniqueGroups.includes(key.split(':')[0])&&b.slots[key]===pieceID)delete b.slots[key];
 if(sourceKey&&sourceKey!==dest){const differentFlyingRole=(m.id==='wave'||m.id==='status')&&sourceKey.split(':')[0]!==lane;if(!differentFlyingRole){delete b.slots[sourceKey];if(previous&&previous!==pieceID)b.slots[sourceKey]=previous;}}
 b.slots[dest]=pieceID;
 if(m.id==='wave'||m.id==='status'||m.id==='phase'){const lanes=m.groups.map(g=>g[0]),i=lanes.indexOf(lane);if(i<lanes.length-1&&Array.from({length:group[1]},(_,j)=>b.slots[lane+':'+j]).every(Boolean))b.active=lanes[i+1];}
 if(m.id==='analysis')b.active=lane==='num'?'den':'num';
 b.selected=null;s.message=null;save();render();}
function autoPlace(id){const m=mission(),b=getBoard();if(m.id==='doc'){b.selected=id;s.message=null;save();render();return;}
 if(m.id==='analysis'){let lane=b.active||'num';if(!['num','den'].includes(lane))lane='num';place(id,lane+':0');return;}
 let lane=b.active||m.groups[0][0],group=groupFor(m,lane);if(!group){lane=m.groups[0][0];group=m.groups[0];}
 let free=Array.from({length:group[1]},(_,i)=>i).find(i=>!b.slots[lane+':'+i]);
 if(free===undefined){const next=m.groups.find(([k,n])=>Array.from({length:n},(_,i)=>i).some(i=>!b.slots[k+':'+i]));if(!next){s.message={ok:false,message:'All slots filled. Tap a filled slot to remove or replace it.'};save();render();return;}lane=next[0];free=Array.from({length:next[1]},(_,i)=>i).find(i=>!b.slots[lane+':'+i]);}
 place(id,lane+':'+free);
}
function onSlot(dest){const m=mission(),b=getBoard(),chosen=b.selected;
 if(chosen&&(['doc'].includes(m.id)||m.id==='analysis'||(m.aircraft&&m.aircraft.some(x=>x.id===chosen)))){place(chosen,dest);return;}
 if(b.slots[dest]){delete b.slots[dest];s.message=null;save();render();return;}
 b.active=dest.split(':')[0];save();render();}
function check(){const m=mission(),b=getBoard();const result=B.evaluate(m.id,m,b,M);
 if(result.needDecision){b.stage='decision';notify(false,result.message);return;}
 if(result.ok){s.reps[m.id]=(s.reps[m.id]||0)+1;if(!b.assisted){if(!s.complete[m.id]){s.complete[m.id]=true;s.score+=100;}else s.score+=20;}
  s.message={ok:true,message:result.message+(b.assisted?' Assisted example: no proficiency credit awarded.':'')};save();render();tone(true);return;}
 notify(false,result.message);}
function showModel(){const m=mission(),b=getBoard();b.assisted=true;b.slots={};b.marked=[];b.choice=null;b.resultChoice=null;
 if(['wave','status'].includes(m.id)){const available=m.aircraft.filter(x=>['FMC','HQ'].includes(x.status));let good=available.slice(0,6);if(m.id==='status'&&!good.some(x=>x.status==='HQ'))good=[...available.filter(x=>x.status==='FMC').slice(0,5),available.find(x=>x.status==='HQ')];good.forEach((x,i)=>b.slots['wave:'+i]=x.id);good.slice(0,4).forEach((x,i)=>b.slots['turn:'+i]=x.id);}
 if(m.id==='phase'){m.aircraft.filter(x=>x.status==='FMC'&&x.hours>=24).forEach((x,i)=>b.slots['fly:'+i]=x.id);b.slots['phase:0']=m.aircraft.find(x=>x.status==='PHASE').id;m.aircraft.filter(x=>x.status==='NMCS'||(x.status==='FMC'&&x.hours<24)).forEach((x,i)=>b.slots['hold:'+i]=x.id);}
 if(m.id==='doc')Object.entries(M.docDowntimeModel()).forEach(([day,stage])=>b.slots['day:'+(Number(day)-1)]=stage);
 if(m.id==='analysis'){b.slots['num:0']=m.metric.num;b.slots['den:0']=m.metric.den;b.resultChoice=m.correct;}
 if(m.id==='integrity'||m.id==='dbm'){b.marked=m.discrepancies.slice();b.stage='decision';b.choice=m.choices.find(x=>x.correct).id;}
 s.message={ok:true,message:'Assisted model loaded. Press CHECK to see the reasoning. Practice without Show model to earn mission credit.'};save();render()}
function hint(){const m=mission();const hints={wave:'All six FMC aircraft fly in the first wave. Four of those SAME aircraft can be scheduled for a second flight.',status:'A hangar queen is not automatically safe to fly. In THIS exercise, the 30-day aircraft has been inspected and is explicitly available. Include it, avoid all NMC, Depot, Phase and PFR blocks.',phase:'The aircraft with zero Phase hours belongs in the Phase dock; the 12-hour aircraft is too near Phase for this planning rule. Supply-NMC cannot fly.',doc:'Put R1 Tuesday, R2 Wednesday, G1 Thursday, G2 Friday, then Cure Saturday. No hand-on work during weekends.',analysis:'Use the exact numerator and denominator named in the metric definition. For a rate expressed as a percentage, multiply the quotient by 100.',integrity:'Three rows differ. Source verification comes before an authorized correction, and the original value must remain auditable.',dbm:'Look for the transferred, over-privileged, and departed accounts. Differences require investigation, not blind deletion.'};notify(true,hints[m.id]);}
function switchMetric(index){const b=getBoard();if(!Number.isInteger(index)||index<0||index>=M.METRICS.length)return;b.metric=index;b.slots={};b.resultChoice=null;b.selected=null;b.assisted=false;s.message=null;save();render()}
function nextCard(direction){const n=deck(s.cards).length;s.card=(s.card+direction+n)%n;s.reveal=false;save();render()}
root.addEventListener('change',e=>{const el=e.target.closest('[data-metric-change]');if(el)switchMetric(Number(el.value));});
root.addEventListener('click',e=>{if(Date.now()<suppressClickUntil)return;const el=e.target.closest('button,[data-start],[data-deck]');if(!el)return;
 if(el.dataset.start){openLevel(el.dataset.start);return;}
 if(el.dataset.deck){s.cards=el.dataset.deck;s.card=0;s.reveal=false;navigate('cards');return;}
 if(el.dataset.flag){const b=getBoard(),id=el.dataset.flag;const a=b.marked||[];b.marked=a.includes(id)?a.filter(x=>x!==id):[...a,id];b.stage='find';b.choice=null;s.message=null;save();render();return;}
 if(el.dataset.choice){getBoard().choice=el.dataset.choice;s.message=null;save();render();return;}
 if(el.dataset.number!==undefined){getBoard().resultChoice=Number(el.dataset.number);s.message=null;save();render();return;}
 if(el.dataset.lane){getBoard().active=el.dataset.lane;getBoard().selected=null;s.message=null;save();render();return;}
 if(el.dataset.slot){onSlot(el.dataset.slot);return;}
 if(el.dataset.bank){autoPlace(el.dataset.bank);return;}
 const cmd=el.dataset.cmd;
 if(cmd==='home'){navigate('home');return;}if(cmd==='sound'){s.sound=!s.sound;save();render();return;}
 if(cmd==='check'){check();return;}if(cmd==='reset'){reset();return;}if(cmd==='variation'){changeVariation();return;}if(cmd==='model'){showModel();return;}if(cmd==='hint'){hint();return;}
 if(cmd==='flip'){s.reveal=!s.reveal;save();render();return;}if(cmd==='card-next'){nextCard(1);return;}if(cmd==='card-back'){nextCard(-1);return;}
});
// Pointer support for draggable blocks. Tap-to-place remains a complete alternative,
// and all targets are normal buttons for VoiceOver and keyboard users.
root.addEventListener('pointerdown',e=>{
 if(s.view!=='play'||e.button!==0)return;const token=e.target.closest('[data-piece]');if(!token)return;
 const id=token.dataset.piece,src=token.closest('[data-slot]')?.dataset.slot||null;
 drag={id,src,pointer:e.pointerId,startX:e.clientX,startY:e.clientY,moved:false,ghost:null};
});
root.addEventListener('pointermove',e=>{
 if(!drag||drag.pointer!==e.pointerId)return;
 if(!drag.moved&&Math.hypot(e.clientX-drag.startX,e.clientY-drag.startY)>10){drag.moved=true;const el=document.createElement('div');el.className='ba-drag-ghost';const info=tileInfo(mission(),drag.id);el.innerHTML=`<b>${E(info.label)}</b><small>${E(info.sub)}</small>`;document.body.appendChild(el);drag.ghost=el;}
 if(!drag.moved)return;e.preventDefault();if(drag.ghost){drag.ghost.style.left=(e.clientX-37)+'px';drag.ghost.style.top=(e.clientY-30)+'px';}
 const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');document.querySelectorAll('.ba-slot.dragtarget,.ba-day.dragtarget').forEach(x=>x.classList.remove('dragtarget'));if(target)target.classList.add('dragtarget');
 if(typeof window.scrollBy==='function'){if(e.clientY<85)window.scrollBy(0,-9);else if(e.clientY>window.innerHeight-75)window.scrollBy(0,9);}
},{passive:false});
root.addEventListener('pointerup',e=>{
 if(!drag||drag.pointer!==e.pointerId)return;const d=drag;drag=null;d.ghost?.remove();document.querySelectorAll('.dragtarget').forEach(x=>x.classList.remove('dragtarget'));
 if(!d.moved)return;suppressClickUntil=Date.now()+250;
 const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('[data-slot]');if(target)place(d.id,target.dataset.slot,d.src);
});
root.addEventListener('pointercancel',()=>{drag?.ghost?.remove();drag=null;});
window.FMBlockAcademy={getState:()=>JSON.parse(JSON.stringify(s)),openLevel,check,showModel,changeVariation,place,mission,render,reset};
render();
})();
